const ORANGE = "#FF5500";
// The card's colour: the fills use it so they hide the dashes without showing as a shape of their own.
const CARD = "#F4F4F4";
const MARKER = "M0.000471211 2.16224C-0.00339091 0.441811 1.93676 -0.588481 3.38881 0.362902L10.3596 4.93013C11.6557 5.77935 11.6609 7.65651 10.3695 8.51271L3.41934 13.1207C1.97172 14.0804 0.0249327 13.0589 0.0210683 11.3374L0.000471211 2.16224Z";
const FONT = '400 16px "LW Inter", Inter, Arial, sans-serif';

// The two lists that turn with the wheel. Seven items each: with five rows on show, the item leaving at the top is
// never the one coming in at the bottom, and seven steps bring the first item back (the loop seam).
const SPECIALTIES = [
  { text: "Longevity Care", w: 147 },
  { text: "Integrative Hormonal", w: 191 },
  { text: "High-Risk Obstetrics", w: 189 },
  { text: "Gynecologic Surgery", w: 190 },
  { text: "Preventive Care", w: 152 },
  { text: "Fertility Care" },
  { text: "Menopause Care" },
];
const DOCTORS = [
  { text: "Dr. Christine", w: 155, pad: 12 },
  { text: "Dr. Lora Shahine", w: 186, pad: 12 },
  { text: "Dr. Alexandra Sowa", w: 209, pad: 12 },
  { text: "Dr. Tamer Seckin", w: 190, pad: 12 },
  { text: "Dr. Sonia", w: 134, pad: 14 },
  { text: "Dr. Maya Chen", pad: 12, initials: "MC" },
  { text: "Dr. Elena Ruiz", pad: 12, initials: "ER" },
];
const N = 7;
const ROW = 64;
const TOP = 433;
const SPEC_RIGHT = 499;
const DOC_X = 1131;
// Opacity by row, from one row above the list (hidden) to one row below it (hidden); the middle row is the active one.
const ROW_ALPHA = [0, 0.3, 0.7, 1, 0.7, 0.3, 0];
const WHEEL = { x: 800, y: 585, r: 369.985 };
const BUTTON = { x: 688, y: 657.59, w: 224, h: 54, r: 50 };

const ORDER = ["design-card", "design-wheel", "design-specialties-fill", "design-specialties", "design-doctors-fill", "design-doctors", "design-heading", "design-subtext", "design-button", "design-cursor"];
const CURSOR_ID = "design-cursor";

const clamp01 = (v) => Math.min(1, Math.max(0, v));
const lerp = (a, b, p) => a + (b - a) * p;
const inOut = (p) => (p < 0.5 ? 4 * p * p * p : 1 - Math.pow(-2 * p + 2, 3) / 2);
const out = (p) => 1 - Math.pow(1 - p, 3);
const prog = (t, span, ease) => (ease || inOut)(clamp01((t - span[0]) / Math.max(0.0001, span[1])));

// The settings and their defaults (Motion › Interaction plan offers each of them).
const DEFAULTS = {
  "start.lead": 0.3,
  "s1.enterTime": 1.0, "s1.hold": 0.5,
  "s2.moveTime": 0.8, "s2.dwell": 0.7, "s2.offTime": 0.35, "s2.gap": 0.35, "s2.leaveTime": 0.6, "s2.hold": 0.3,
  "s3.moveTime": 0.8, "s3.iconTime": 0.25, "s3.steps": 2, "s3.forwardTime": 1.2, "s3.backTime": 1.2, "s3.hold": 0.1,
  "s4.pause": 0.5, "s4.exitTime": 0.8, "s4.hold": 0.3,
  "loop.on": true, "loop.stepTime": 0.7, "loop.arc": true, "loop.outScale": 70,
  "spin.on": true, "spin.returnTime": 0.6,
  "hover.on": true, "hover.time": 0.35, "hover.color": "#111111", "hover.roll": 34,
  "line.on": true, "line.width": 2.5, "line.offset": 30, "line.color": ORANGE,
  "specialties.blur": 0, "doctors.blur": 0,
  "specialties-fill.blur": 8, "doctors-fill.blur": 8, "specialties-fill.opacity": 100, "doctors-fill.opacity": 100,
  "specialties-fill.height": 0, "doctors-fill.height": 0, "specialties-fill.width": 40, "doctors-fill.width": 40,
  "specialties-fill.padding": 0, "doctors-fill.padding": 0, "specialties-fill.softness": 0, "doctors-fill.softness": 0,
};
const val = (P, key) => {
  const v = P && P[key];
  if (typeof v === "number" && Number.isFinite(v)) return v;
  if (typeof v === "boolean") return v;
  if (typeof v === "string" && /^#[0-9a-fA-F]{6}$/.test(v)) return v;
  return DEFAULTS[key];
};

// Where the cursor goes.
const P_START = { x: 1720, y: 1290 };
const P_REST = { x: 1050, y: 840 };
const P_BUTTON = { x: 826, y: 690 };
const P_OFF = { x: 846, y: 760 };
const P_AWAY = { x: 1010, y: 800 };
const P_GRAB = { x: 1262, y: 588 };

// When a move (eased like the cursor's) first has the tip inside (entering) or outside (leaving) the button.
function onButton(at) {
  return at.x >= BUTTON.x && at.x <= BUTTON.x + BUTTON.w && at.y >= BUTTON.y && at.y <= BUTTON.y + BUTTON.h;
}
function crossing(span, from, to, entering) {
  const STEPS = 240;
  for (let i = 0; i <= STEPS; i += 1) {
    const at = mix(from, to, inOut(i / STEPS));
    if (onButton(at) === entering) return span[0] + (span[1] * i) / STEPS;
  }
  return span[0] + span[1];
}

// The time of every part, from the settings. The loop ends where it started.
function schedule(P) {
  const T = {};
  let t = val(P, "start.lead");
  // 01: the cursor comes in, then pauses.
  T.enter = [t, val(P, "s1.enterTime")];
  t += T.enter[1] + val(P, "s1.hold");
  T.s2 = t;
  // 02: hover Schedule Now twice, then leave it.
  const hover = val(P, "s2.offTime");
  T.toButton = [t, val(P, "s2.moveTime")]; t += T.toButton[1];
  t += val(P, "s2.dwell");
  T.off = [t, hover]; t += hover + val(P, "s2.gap");
  T.back = [t, hover]; t += hover + val(P, "s2.dwell");
  T.leave = [t, val(P, "s2.leaveTime")]; t += T.leave[1] + val(P, "s2.hold");
  // The hover starts the moment the cursor's tip crosses into the button and ends the moment it crosses out.
  T.hoverIn1 = crossing(T.toButton, P_REST, P_BUTTON, true);
  T.hoverOut1 = crossing(T.off, P_BUTTON, P_OFF, false);
  T.hoverIn2 = crossing(T.back, P_OFF, P_BUTTON, true);
  T.hoverOut2 = crossing(T.leave, P_BUTTON, P_AWAY, false);
  T.s3 = t;
  // 03: to the doctors list, the cursor turns into a hand, scrolls forward, then back.
  T.toGrab = [t, val(P, "s3.moveTime")]; t += T.toGrab[1];
  T.icon = t; t += val(P, "s3.iconTime");
  T.press = t;
  T.forward = [t, val(P, "s3.forwardTime")]; t += T.forward[1];
  T.backward = [t, val(P, "s3.backTime")]; t += T.backward[1];
  T.release = t; t += 0.1 + val(P, "s3.hold");
  T.s4 = t;
  // 04: a pause, then out of the screen.
  t += val(P, "s4.pause");
  T.exit = [t, val(P, "s4.exitTime")]; t += T.exit[1] + val(P, "s4.hold");
  T.total = t;
  return T;
}

// The cursor: where its tip is, and whether it is the arrow or the grabbing hand.
function cursorAt(T, t) {
  if (t < T.enter[0] || t >= T.exit[0] + T.exit[1]) return null;
  let at = P_START;
  if (t < T.s2) at = { x: lerp(P_START.x, P_REST.x, prog(t, T.enter, out)), y: lerp(P_START.y, P_REST.y, prog(t, T.enter, out)) };
  else if (t < T.off[0]) at = mix(P_REST, P_BUTTON, prog(t, T.toButton));
  else if (t < T.back[0]) at = mix(P_BUTTON, P_OFF, prog(t, T.off));
  else if (t < T.leave[0]) at = mix(P_OFF, P_BUTTON, prog(t, T.back));
  else if (t < T.s3) at = mix(P_BUTTON, P_AWAY, prog(t, T.leave));
  else if (t < T.press) at = mix(P_AWAY, P_GRAB, prog(t, T.toGrab));
  else if (t < T.exit[0]) at = { x: P_GRAB.x, y: P_GRAB.y + handOffset(T, t) };
  else at = mix(P_GRAB, P_START, prog(t, T.exit, (p) => p * p * p));
  const hand = t >= T.icon && t < T.release + 0.05;
  return { kind: hand ? "hand" : "arrow", x: at.x, y: at.y };
}
function mix(a, b, p) {
  return { x: lerp(a.x, b.x, p), y: lerp(a.y, b.y, p) };
}

// The hand's drag while scrolling: up by the scroll (forward), then back down to where it grabbed (backward).
let scrollRows = 2;
function handOffset(T, t) {
  const reach = scrollRows * ROW;
  if (t < T.forward[0]) return 0;
  if (t < T.backward[0]) return -reach * prog(t, T.forward);
  if (t < T.release) return -reach * (1 - prog(t, T.backward));
  return 0;
}

// How far the lists have turned, in rows: the loop's own steps (seven, one at a time, paused while scrolling) plus
// the scroll. Forward is up (the next item comes in at the bottom) and turns the wheel clockwise.
function stepsAt(P, T, t) {
  let steps = 0;
  if (val(P, "loop.on")) {
    // The seven steps are shared between the time before the scroll and the time after it, evenly in each, so a step
    // is never caught half-way when the hand grabs the list.
    const windows = [[0, T.toGrab[0]], [T.release + 0.1, T.total]];
    const lengths = windows.map(([a, b]) => Math.max(0, b - a));
    const before = Math.min(N, Math.max(lengths[1] > 0.6 ? 0 : N, Math.round((N * lengths[0]) / (lengths[0] + lengths[1]))));
    const counts = [before, N - before];
    windows.forEach(([a], w) => {
      const count = counts[w];
      if (count <= 0) return;
      const gap = lengths[w] / count;
      const span = Math.min(val(P, "loop.stepTime"), gap * 0.8);
      for (let k = 0; k < count; k += 1) {
        const centre = a + (k + 0.5) * gap;
        steps += inOut(clamp01((t - (centre - span / 2)) / span));
      }
    });
  }
  steps += -handOffset(T, t) / ROW;
  return steps;
}

// The wheel turns only with the scroll (clockwise forward, back again), then eases home from wherever the scroll left it,
// so every loop starts and ends with the wheel in its own place.
function spinRows(P, T, t) {
  if (t < T.press) return 0;
  if (t < T.release) return -handOffset(T, t) / ROW;
  const left = -handOffset(T, T.release - 1e-6) / ROW;
  return left * (1 - prog(t, [T.release, val(P, "spin.returnTime")]));
}

// Schedule Now hover: 0 (off) to 1 (on), eased over Hover time at each hover in and out.
function hoverAt(P, T, t) {
  if (!val(P, "hover.on")) return 0;
  const time = val(P, "hover.time");
  const events = [[T.hoverIn1, 1], [T.hoverOut1, 0], [T.hoverIn2, 1], [T.hoverOut2, 0]];
  let h = 0;
  for (const [at, target] of events) {
    if (t < at) break;
    h = lerp(h, target, inOut(clamp01((t - at) / time)));
  }
  return h;
}

function rowAlpha(row) {
  if (row <= -1 || row >= 5) return 0;
  const i = Math.floor(row + 1);
  return lerp(ROW_ALPHA[i], ROW_ALPHA[i + 1], row + 1 - i);
}

// Where each item of a list is: its row (0 top ... 2 middle ... 4 bottom; fractions while it moves) and opacity.
function listRows(steps) {
  const rows = [];
  for (let i = 0; i < N; i += 1) {
    let rel = (((i - 2 - steps) % N) + N) % N;
    if (rel > N / 2) rel -= N;
    const row = rel + 2;
    const alpha = rowAlpha(row);
    if (alpha > 0.001) rows.push({ alpha, i, row, y: TOP + row * ROW });
  }
  return rows;
}

// Where an item of a list sits for its row: on a circle around the wheel's centre (Path on), the middle row where the
// design has it, the rows above and below curving toward the wheel; and how big it is (Out scale on the way out of
// the list and on the way in, full size on the five rows on show). The anchor is the pill's edge nearest the wheel.
function rowPlace(P, row, left, w) {
  const middle = TOP + row * ROW + 24;
  let anchor = left ? SPEC_RIGHT : DOC_X;
  if (val(P, "loop.arc")) {
    const radius = left ? WHEEL.x - SPEC_RIGHT : DOC_X - WHEEL.x;
    const dy = middle - WHEEL.y;
    const dx = Math.sqrt(Math.max(0, radius * radius - dy * dy));
    anchor = left ? WHEEL.x - dx : WHEEL.x + dx;
  }
  const out = val(P, "loop.outScale") / 100;
  const scale = row < 0 ? lerp(1, out, clamp01(-row)) : row > 4 ? lerp(1, out, clamp01(row - 4)) : 1;
  return { anchor, middle, scale, x: left ? anchor - w : anchor, y: middle - 24 };
}
function placeAt(ctx, place) {
  ctx.translate(place.anchor, place.middle);
  ctx.scale(place.scale, place.scale);
  ctx.translate(-place.anchor, -place.middle);
}

const images = {};
let doctorImages = [];
let womanhood = null;
const widths = new Map();

function textWidth(ctx, text) {
  if (!widths.has(text)) {
    ctx.save();
    ctx.font = FONT;
    widths.set(text, ctx.measureText(text).width);
    ctx.restore();
  }
  return widths.get(text);
}
function specWidth(ctx, item) {
  return item.w || Math.round(textWidth(ctx, item.text) + 48);
}
function docWidth(ctx, item) {
  return item.w || Math.round(item.pad + 38 + textWidth(ctx, item.text) + 22);
}

function loadImage(src) {
  return new Promise((resolve, reject) => {
    const image = new Image();
    image.onload = () => resolve(image);
    image.onerror = () => reject(new Error("An image failed to load."));
    image.src = src;
  });
}

// Some browsers (Safari) ignore ctx.filter; they get a downscale blur instead.
const CAN_FILTER = (() => {
  try {
    const probe = new OffscreenCanvas(1, 1).getContext("2d");
    probe.filter = "blur(2px)";
    return probe.filter === "blur(2px)";
  } catch (error) {
    return false;
  }
})();
const scratch = [null, null];

function blurBehind(ctx, x, y, w, blur) {
  ctx.save();
  ctx.beginPath();
  ctx.roundRect(x, y, w, 48, 24);
  ctx.clip();
  const m = ctx.getTransform();
  const scale = m.a;
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  if (CAN_FILTER) {
    ctx.filter = "blur(" + blur * scale + "px)";
    ctx.drawImage(ctx.canvas, 0, 0);
  } else {
    const px = Math.max(0, Math.floor(m.e + x * scale) - 1);
    const py = Math.max(0, Math.floor(m.f + y * scale) - 1);
    const pw = Math.ceil(w * scale) + 2;
    const ph = Math.ceil(48 * scale) + 2;
    const steps = Math.max(1, Math.round(Math.log2(Math.max(1, (blur * scale) / 2))) + 3);
    let from = ctx.canvas;
    let fx = px;
    let fy = py;
    let fw = pw;
    let fh = ph;
    for (let i = 0; i < steps; i += 1) {
      const nw = Math.max(1, Math.ceil(fw / 2));
      const nh = Math.max(1, Math.ceil(fh / 2));
      const to = (scratch[i % 2] = scratch[i % 2] || new OffscreenCanvas(1, 1));
      to.width = nw;
      to.height = nh;
      const tctx = to.getContext("2d");
      tctx.imageSmoothingEnabled = true;
      tctx.imageSmoothingQuality = "high";
      tctx.drawImage(from, fx, fy, fw, fh, 0, 0, nw, nh);
      from = to;
      fx = 0;
      fy = 0;
      fw = nw;
      fh = nh;
    }
    ctx.imageSmoothingEnabled = true;
    ctx.imageSmoothingQuality = "high";
    ctx.drawImage(from, 0, 0, fw, fh, px, py, pw, ph);
  }
  ctx.restore();
}

function pill(ctx, x, y, w, alpha, blur) {
  if (blur > 0 && alpha > 0.01) blurBehind(ctx, x, y, w, blur);
  ctx.save();
  ctx.globalAlpha *= alpha;
  ctx.beginPath();
  ctx.roundRect(x, y, w, 48, 24);
  ctx.fillStyle = ORANGE;
  ctx.fill();
  ctx.restore();
}

function label(ctx, text, x, y, align, alpha) {
  ctx.save();
  ctx.globalAlpha *= alpha;
  ctx.font = FONT;
  ctx.letterSpacing = "0px";
  ctx.fillStyle = "#FFFFFF";
  ctx.textAlign = align;
  ctx.textBaseline = "middle";
  ctx.fillText(text, x, y);
  ctx.restore();
}

function marker(ctx, x, y, flip) {
  ctx.save();
  ctx.translate(x + 6, y + 7);
  if (flip) ctx.rotate(Math.PI);
  ctx.translate(-6, -7);
  ctx.fillStyle = ORANGE;
  ctx.fill(new Path2D(MARKER));
  ctx.restore();
}

// A canvas the size of the frame for the wheel, reused between frames, drawn with the frame's own transform.
let wheelCanvas = null;
function wheelLayer(ctx) {
  const w = ctx.canvas.width;
  const h = ctx.canvas.height;
  if (!wheelCanvas || wheelCanvas.width !== w || wheelCanvas.height !== h) wheelCanvas = new OffscreenCanvas(w, h);
  const layer = wheelCanvas.getContext("2d");
  layer.setTransform(1, 0, 0, 1, 0, 0);
  layer.clearRect(0, 0, w, h);
  layer.setTransform(ctx.getTransform());
  layer.imageSmoothingEnabled = true;
  layer.imageSmoothingQuality = "high";
  return layer;
}

// Cuts each pill's shape (grown by its padding) out of the wheel layer at full strength; Softness feathers the edge
// (drawn as a shadow so it works in every browser).
function cutOut(layer, cuts) {
  const OFFSET = 6000;
  layer.save();
  layer.globalCompositeOperation = "destination-out";
  layer.fillStyle = "#000";
  for (const cut of cuts) {
    if (cut.strength !== undefined && cut.strength <= 0) continue;
    layer.save();
    layer.globalAlpha = cut.strength === undefined ? 1 : cut.strength;
    if (cut.place) placeAt(layer, cut.place);
    const scale = layer.getTransform().a;
    const soft = cut.soft;
    layer.shadowColor = soft > 0 ? "#000" : "transparent";
    layer.shadowBlur = soft * scale;
    layer.shadowOffsetX = soft > 0 ? OFFSET : 0;
    const shift = soft > 0 ? OFFSET / scale : 0;
    layer.beginPath();
    layer.roundRect(cut.x - cut.pad - shift, cut.y - cut.pad, cut.w + cut.pad * 2, cut.h + cut.pad * 2, 24 + cut.pad);
    layer.fill();
    layer.restore();
  }
  layer.restore();
}

function initialsAvatar(ctx, cx, cy, text) {
  ctx.save();
  ctx.beginPath();
  ctx.arc(cx, cy, 14, 0, Math.PI * 2);
  ctx.fillStyle = "#FFE1D3";
  ctx.fill();
  ctx.fillStyle = ORANGE;
  ctx.font = '600 11px "LW Inter", Inter, Arial, sans-serif';
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  ctx.fillText(text, cx, cy + 0.5);
  ctx.restore();
}

// The same shapes as the Reactor's desktop cursor and grabbing hand.
const CURSOR_SIZE = 40;
function drawCursor(ctx, at) {
  const s = CURSOR_SIZE;
  ctx.save();
  if (at.kind === "hand") {
    const hs = s * 1.35;
    drawHand(ctx, at.x - 0.4 * hs, at.y - 0.42 * hs, hs);
    ctx.restore();
    return;
  }
  ctx.translate(at.x, at.y);
  ctx.beginPath();
  ctx.moveTo(0, 0);
  ctx.lineTo(0, s * 0.98);
  ctx.lineTo(s * 0.25, s * 0.76);
  ctx.lineTo(s * 0.42, s * 1.16);
  ctx.lineTo(s * 0.57, s * 1.1);
  ctx.lineTo(s * 0.41, s * 0.72);
  ctx.lineTo(s * 0.72, s * 0.72);
  ctx.closePath();
  ctx.fillStyle = "#111111";
  ctx.fill();
  ctx.lineJoin = "round";
  ctx.lineWidth = Math.max(1.5, s * 0.07);
  ctx.strokeStyle = "#FFFFFF";
  ctx.stroke();
  ctx.restore();
}
function drawHand(ctx, x, y, s) {
  const lw = Math.max(1.5, s * 0.07);
  ctx.beginPath();
  ctx.roundRect(x + 0.1 * s, y + 0.26 * s, 0.62 * s, 0.46 * s, 0.16 * s);
  for (const kx of [0.2, 0.355, 0.51, 0.64]) {
    ctx.moveTo(x + (kx + 0.085) * s, y + 0.27 * s);
    ctx.arc(x + kx * s, y + 0.27 * s, 0.085 * s, 0, Math.PI * 2);
  }
  ctx.moveTo(x + 0.185 * s, y + 0.46 * s);
  ctx.ellipse(x + 0.1 * s, y + 0.46 * s, 0.085 * s, 0.14 * s, 0, 0, Math.PI * 2);
  ctx.lineJoin = "round";
  ctx.lineWidth = lw * 2;
  ctx.strokeStyle = "#FFFFFF";
  ctx.stroke();
  ctx.fillStyle = "#111111";
  ctx.fill("nonzero");
  ctx.lineCap = "round";
  ctx.lineWidth = lw * 0.6;
  ctx.beginPath();
  for (const gx of [0.2775, 0.4325, 0.575]) {
    ctx.moveTo(x + gx * s, y + 0.23 * s);
    ctx.lineTo(x + gx * s, y + 0.36 * s);
  }
  ctx.stroke();
}

function hexMix(a, b, p) {
  const ca = parseInt(a.slice(1), 16);
  const cb = parseInt(b.slice(1), 16);
  const ch = (shift) => Math.round(lerp((ca >> shift) & 255, (cb >> shift) & 255, p));
  return "rgb(" + ch(16) + "," + ch(8) + "," + ch(0) + ")";
}

// Everything that moves at time t.
function stateAt(P, t, shown) {
  const T = schedule(P);
  scrollRows = val(P, "s3.steps");
  const time = ((t % T.total) + T.total) % T.total;
  const steps = stepsAt(P, T, time);
  return {
    cursor: cursorAt(T, time),
    hover: hoverAt(P, T, time),
    masks: { doctors: !shown || shown.has("design-doctors-fill"), specialties: !shown || shown.has("design-specialties-fill") },
    rows: listRows(steps),
    // Wheel follows: "lists" turns it with every list step (one full turn a loop, v_01); "scroll" only with the scroll.
    spin: val(P, "spin.on") ? (((P && P["spin.follow"] === "lists") ? steps : spinRows(P, T, time)) * Math.PI * 2) / N : 0,
    total: T.total,
  };
}

function drawLayer(ctx, id, P, state) {
  switch (id) {
    case "design-card":
      ctx.beginPath();
      ctx.roundRect(90, 75, 1420, 1020, 16);
      ctx.fillStyle = CARD;
      ctx.fill();
      break;
    case "design-wheel": {
      if (!images.wheel) break;
      // The wheel is drawn on its own layer so the pills can cut their shapes out of it (Specialties mask, Doctors mask):
      // where a pill is, there is no wheel, however faint the pill is.
      const cuts = [];
      for (const side of ["specialties", "doctors"]) {
        if (!state.masks[side]) continue;
        const left = side === "specialties";
        const pad = Math.max(0, val(P, side + "-fill.padding"));
        const soft = Math.max(0, val(P, side + "-fill.softness"));
        for (const row of state.rows) {
          const w = left ? specWidth(ctx, SPECIALTIES[row.i]) : docWidth(ctx, DOCTORS[row.i]);
          const place = rowPlace(P, row.row, left, w);
          // Full strength on the five rows on show; in and out of the list it fades with the item's own entry and exit
          // (the same move that scales it), so the cut never shows before the item or stays after it.
          const strength = row.row < 0 ? clamp01(1 + row.row) : row.row > 4 ? clamp01(5 - row.row) : 1;
          cuts.push({ h: 48, pad, place, soft, strength, w, x: place.x, y: place.y });
        }
      }
      const target = cuts.length > 0 ? wheelLayer(ctx) : ctx;
      target.save();
      target.beginPath();
      target.arc(WHEEL.x, WHEEL.y, WHEEL.r, 0, Math.PI * 2);
      target.clip();
      target.translate(WHEEL.x, WHEEL.y);
      target.rotate(state.spin);
      target.translate(-WHEEL.x, -WHEEL.y);
      target.drawImage(images.wheel, 430 - 69.158, 215 - 69.159, 878.288, 878.288);
      target.restore();
      if (target !== ctx) {
        cutOut(target, cuts);
        ctx.save();
        ctx.setTransform(1, 0, 0, 1, 0, 0);
        ctx.drawImage(target.canvas, 0, 0);
        ctx.restore();
      }
      break;
    }
    case "design-specialties-fill":
    case "design-doctors-fill":
      // The masks work on the wheel (above); they draw nothing themselves.
      break;
    case "design-specialties":
      marker(ctx, 284, 578, false);
      for (const row of state.rows) {
        const item = SPECIALTIES[row.i];
        const w = specWidth(ctx, item);
        const place = rowPlace(P, row.row, true, w);
        ctx.save();
        placeAt(ctx, place);
        pill(ctx, place.x, place.y, w, row.alpha, val(P, "specialties.blur"));
        label(ctx, item.text, place.x + w / 2, place.middle, "center", row.alpha);
        ctx.restore();
      }
      break;
    case "design-doctors":
      marker(ctx, 1364, 592, true);
      for (const row of state.rows) {
        const item = DOCTORS[row.i];
        const w = docWidth(ctx, item);
        const place = rowPlace(P, row.row, false, w);
        const x = place.x;
        const y = place.y;
        ctx.save();
        placeAt(ctx, place);
        pill(ctx, x, y, w, row.alpha, val(P, "doctors.blur"));
        const cx = x + item.pad + 14;
        const cy = place.middle;
        ctx.save();
        ctx.globalAlpha *= row.alpha;
        const avatar = doctorImages[row.i];
        if (avatar) {
          ctx.beginPath();
          ctx.arc(cx, cy, 14, 0, Math.PI * 2);
          ctx.clip();
          ctx.drawImage(avatar, x + item.pad, y + 10, 28, 28);
        } else {
          initialsAvatar(ctx, cx, cy, item.initials || item.text.replace(/^Dr\.\s*/, "").slice(0, 2).toUpperCase());
        }
        ctx.restore();
        label(ctx, item.text, x + item.pad + 38, cy, "left", row.alpha);
        ctx.restore();
      }
      break;
    case "design-heading": {
      ctx.save();
      ctx.textBaseline = "middle";
      ctx.textAlign = "center";
      ctx.fillStyle = "#020202";
      ctx.letterSpacing = "-0.96px";
      ctx.font = '600 48px "LW Inter", Inter, Arial, sans-serif';
      ctx.fillText("Care for every step", 805, 488.4);
      const sans = '600 48px "LW Inter", Inter, Arial, sans-serif';
      const serif = 'italic 400 48px "LW Instrument Serif", "Instrument Serif", Georgia, serif';
      const parts = [[" of ", sans], ["Womanhood", serif], [".", sans]];
      let total = 0;
      for (const [text, font] of parts) {
        ctx.font = font;
        total += ctx.measureText(text).width;
      }
      ctx.textAlign = "left";
      let x = 805 - total / 2;
      for (const [text, font] of parts) {
        ctx.font = font;
        const w = ctx.measureText(text).width;
        if (text === "Womanhood") womanhood = { w, x, y: 541.2 };
        ctx.fillText(text, x, 541.2);
        x += w;
      }
      ctx.restore();
      // The line under "Womanhood" opens from the word's centre while Schedule Now is hovered.
      if (womanhood && val(P, "line.on") && state.hover > 0.001) {
        const half = (womanhood.w * state.hover) / 2;
        const cx = womanhood.x + womanhood.w / 2;
        ctx.save();
        ctx.strokeStyle = val(P, "line.color") || ORANGE;
        ctx.lineWidth = val(P, "line.width");
        ctx.lineCap = "round";
        ctx.beginPath();
        ctx.moveTo(cx - half, womanhood.y + val(P, "line.offset"));
        ctx.lineTo(cx + half, womanhood.y + val(P, "line.offset"));
        ctx.stroke();
        ctx.restore();
      }
      break;
    }
    case "design-subtext": {
      ctx.save();
      ctx.textBaseline = "middle";
      ctx.textAlign = "center";
      ctx.fillStyle = "#4B5563";
      ctx.letterSpacing = "0px";
      ctx.font = FONT;
      ctx.fillText("From routine gynecology to maternity and fertility care, our", 805, 591.6);
      ctx.fillText("specialists offer compassionate, personalized support.", 805, 615.6);
      ctx.restore();
      break;
    }
    case "design-button": {
      // Hover: the colour changes; the label rolls out of the top while a copy rolls in from the bottom.
      const h = state.hover;
      ctx.save();
      ctx.beginPath();
      ctx.roundRect(BUTTON.x, BUTTON.y, BUTTON.w, BUTTON.h, BUTTON.r);
      ctx.fillStyle = h > 0 ? hexMix(ORANGE, val(P, "hover.color") || "#111111", h) : ORANGE;
      ctx.fill();
      ctx.clip();
      ctx.fillStyle = "#FFFFFF";
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      ctx.letterSpacing = "-0.32px";
      ctx.font = '600 16px "LW Inter", Inter, Arial, sans-serif';
      const roll = val(P, "hover.roll");
      ctx.fillText("SCHEDULE NOW", 799.64, 684.59 - h * roll);
      if (h > 0) ctx.fillText("SCHEDULE NOW", 799.64, 684.59 + (1 - h) * roll);
      ctx.restore();
      break;
    }
    case CURSOR_ID:
      if (state.cursor) drawCursor(ctx, state.cursor);
      break;
  }
}

return {
  async init() {
    await Promise.all(
      api.fonts.map(async (font) => {
        const source = api.assets[font.asset];
        if (!source) return;
        const face = new FontFace(font.family, `url(${source})`, { style: font.asset.includes("italic") ? "italic" : "normal", weight: font.weight });
        await face.load();
        document.fonts.add(face);
      }),
    );
    if (api.assets.wheel) images.wheel = await loadImage(api.assets.wheel);
    const doctors = api.imageAssets.filter((name) => name.startsWith("doctor-"));
    doctorImages = await Promise.all(doctors.map((name) => loadImage(api.assets[name] ?? "")));
  },
  // When each segment starts and ends for the given settings (the cards of the Interaction plan), and when each effect works.
  getSegments(P) {
    const T = schedule(P || {});
    const hold = (key) => val(P || {}, key);
    return [
      { id: "01", name: "01 · Cursor in", start: 0, end: T.s2, hold: hold("s1.hold"), items: [{ item: "Cursor", where: "comes in from the bottom right, then pauses" }] },
      { id: "02", name: "02 · Button hover", start: T.s2, end: T.s3, hold: hold("s2.hold"), items: [
        { item: "Cursor", where: "hovers Schedule Now twice, then leaves it" },
        { item: "Schedule Now", where: "colour changes, label rolls" },
        { item: "Womanhood", where: "line opens from the centre" } ] },
      { id: "03", name: "03 · Scroll", start: T.s3, end: T.s4, hold: hold("s3.hold"), items: [
        { item: "Cursor", where: "turns into a hand, scrolls forward, then back" },
        { item: "Wheel", where: "turns clockwise, then back" },
        { item: "Doctors · Specialties", where: "follow the scroll" } ] },
      { id: "04", name: "04 · Cursor out", start: T.s4, end: T.total, hold: hold("s4.hold"), items: [{ item: "Cursor", where: "pauses, then leaves the screen" }] },
      { id: "fx:List loop", name: "List loop", start: 0, end: T.total, hold: 0, items: [
        { item: "Doctors", where: "turn one by one; top fades out, bottom fades in" },
        { item: "Specialties", where: "same steps, same direction" } ] },
      { id: "fx:Wheel spin", name: "Wheel spin", start: T.press, end: T.release + hold("spin.returnTime"), hold: 0, items: [{ item: "Wheel", where: "turns only with the scroll, then back home" }] },
      { id: "fx:Button hover", name: "Button hover", start: T.hoverIn1, end: T.hoverOut2 + hold("hover.time"), hold: 0, items: [{ item: "Schedule Now", where: "colour and rolling label" }] },
      { id: "fx:Womanhood line", name: "Womanhood line", start: T.hoverIn1, end: T.hoverOut2 + hold("hover.time"), hold: 0, items: [{ item: "Womanhood", where: "line under the word" }] },
    ];
  },
  render(ctx, frame) {
    const scale = frame.pixelScale;
    ctx.setTransform(scale, 0, 0, scale, 0, 0);
    ctx.imageSmoothingEnabled = true;
    ctx.imageSmoothingQuality = "high";
    const P = frame.params || {};
    const shown = new Set(frame.layerStack);
    const state = stateAt(P, frame.timeSeconds || 0, shown);
    for (const id of ORDER) {
      if (shown.has(id)) drawLayer(ctx, id, P, state);
    }
  },
};
